<?php

namespace Bga\Games\RegroupChickenArmy\States;

use Bga\Games\RegroupChickenArmy\Components\Boards;
use Bga\Games\RegroupChickenArmy\Game;
use BgaUserException;
use Bga\Games\RegroupChickenArmy\Components\Market;
use Bga\Games\RegroupChickenArmy\Components\Players;
use Bga\Games\RegroupChickenArmy\Components\Resources;
use BgaVisibleSystemException;

class PlayerTurnStateHandler implements StateHandlerInterface
{
    /* AUTOGENERATED_HANDLE_START - DO NOT REMOVE THIS COMMENT */
    public static function handle(Game $game, string $action, ...$args): void
    {
        switch ($action) {
            case 'pickDeckCard':
                self::pickDeckCard($game);
                break;
            case 'putCard':
                self::putCard($game, $args[0], $args[1], $args[2], $args[3]);
                break;
            default:
                throw new BgaVisibleSystemException("Invalid action: $action");
        }
    }
    /* AUTOGENERATED_HANDLE_END - DO NOT REMOVE THIS COMMENT */

    /* AUTOGENERATED_METHOD - putCard */
    private static function putCard(Game $game, int $cardId, int $rotation, int $posX, int $posY): void
    {
        $game->trace("Player placing card ID: $cardId at position [$posX,$posY] with rotation: $rotation");

        $rotation = (($rotation % 4) + 4) % 4;

        $playerId = (int) $game->getCurrentPlayerId();
        // $playerName = $game->getActivePlayerName(); // Uncomment if needed for notifications
        $leaderId = (int) $game->getUniqueValueFromDB("SELECT leader_id FROM playerData WHERE player_id = $playerId");
        $game->debug("Player ID: $playerId with leader ID: $leaderId placing card");

        // Check if player is using a card from the deck
        $deckCardId = $game->getUniqueValueFromDB("SELECT marketCardPicked FROM playerData WHERE player_id = $playerId");
        if ($deckCardId !== null) {
            $game->debug("Player has deck card picked ID: $deckCardId");
            // Player is using a deck card
            if ($cardId != $deckCardId) {
                $game->trace("Player trying to use wrong card, expected deck card ID: $deckCardId");
                throw new BgaUserException(clienttranslate("You must use the card you picked from the deck"));
            }
            $game->debug("Player using correct deck card");

            // Place the card on the player's board
            $game->debug("Placing deck card on board");
            Boards::putCardOnBoard($game, $leaderId, $cardId, $rotation, $posX, $posY);

            $game->debug("Removing card from market");
            Market::removeMarketCard($game, $deckCardId);

            $game->trace("Notifying players about card placement");
            $game->notifyAllPlayers('cardPlaced', clienttranslate('${player_name} placed a card ${card_id_formatted}'), [
                'player_name' => $game->getActivePlayerName(),
                'player_id' => $game->getActivePlayerId(),
                'board_id' => $leaderId,
                'card_id' => $cardId,
                'rotation' => $rotation,
                'x' => $posX,
                'y' => $posY,
                'isDeckCard' => true
            ]);

            // Clear the picked card
            $game->debug("Clearing picked card from player record");
            $game->DbQuery("UPDATE playerData SET marketCardPicked = NULL WHERE player_id = $playerId");

            // Update resources based on the new card
            $game->debug("Updating resources based on new card placement");

            Resources::updateResourcesFromBoard($game, $leaderId);

            $game->trace("Deck card placement complete, ending turn");
            $game->gamestate->nextState("turnEnded");
            return;
        }

        // Player is using a market card
        $game->trace("Player attempting to use market card");
        $marketCards = Market::getAllMarketCards($game);
        $cardFound = false;
        $cardCost = 0;

        foreach ($marketCards as $index => $marketCard) {
            if ($marketCard['card_id'] == $cardId) {
                $cardFound = true;
                $cardCost = $index;
                break;
            }
        }

        if (!$cardFound) {
            $game->trace("Card ID: $cardId not found in market");
            throw new BgaUserException(clienttranslate("This card is not available in the market"));
        }
        $game->debug("Card found in market at position $cardCost");

        // Check if player has enough coins
        $playerCoins = $game->getUniqueValueFromDB(
            "SELECT coin FROM resources WHERE leader_id = $leaderId"
        );
        $game->debug("Player has $playerCoins coins, card cost is $cardCost");

        if ($playerCoins < $cardCost) {
            $game->trace("Player doesn't have enough coins to buy card");
            throw new BgaUserException(clienttranslate("You don't have enough coins to buy this card"));
        }
        $game->debug("Player has enough coins to buy card");

        // Place the card on the player's board
        $game->debug("Placing market card on board");
        Boards::putCardOnBoard($game, $leaderId, $cardId, $rotation, $posX, $posY);

        $game->debug("Removing card from market");
        Market::removeMarketCard($game, $cardId);

        $game->trace("Notifying players about card placement");
        $game->notifyAllPlayers('cardPlaced', clienttranslate('${player_name} placed a card ${card_id_formatted}'), [
            'player_name' => $game->getActivePlayerName(),
            'player_id' => $game->getActivePlayerId(),
            'board_id' => $leaderId,
            'card_id' => $cardId,
            'rotation' => $rotation,
            'x' => $posX,
            'y' => $posY,
            'isDeckCard' => false
        ]);

        // Update resources based on the new card
        $game->debug("Updating resources based on new card placement");
        Resources::updateResourcesFromBoard($game, $leaderId);

        $game->trace("Market card placement complete, ending turn");
        $game->gamestate->nextState("turnEnded");
    }

    /* AUTOGENERATED_METHOD - pickDeckCard */
    private static function pickDeckCard(Game $game): void
    {
        $game->trace("Player picking a card from the deck");
        $playerId = (int) $game->getCurrentPlayerId();
        $playerName = $game->getActivePlayerName();
        $game->debug("Player ID: $playerId ($playerName) picking deck card");

        $hasAlreadyPickADeckCard = $game->getUniqueValueFromDB(
            "SELECT `marketCardPicked` FROM `playerData` WHERE `player_id` = $playerId"
        );

        if ($hasAlreadyPickADeckCard != null) {
            $game->trace("Player already has a deck card ID: $hasAlreadyPickADeckCard");
            $game->gamestate->nextState('retry');
            throw new BgaUserException(clienttranslate("You alreay had picked a deck card!"));
        }
        $game->debug("Player eligible to pick a deck card");
        $deckCardId = Market::getMarketCard($game, 3);
        $game->debug("Retrieved deck card ID: $deckCardId");

        $game->debug("Assigning deck card to player");
        $game->DbQuery("UPDATE playerData SET marketCardPicked = $deckCardId WHERE player_id = $playerId");

        $game->trace("Notifying all players about deck card pick");
        $game->notifyAllPlayers('deckCardPicked', clienttranslate('${player_name} picked a card from the deck.'), [
            'player_name' => $playerName,
            'player_id' => $playerId,
            'card_id' => $deckCardId
        ]);

        $game->trace("Deck card pick complete, moving to next state");
        $game->gamestate->nextState("deckCardPicked");
    }

    public static function executeGameState(Game $game): void
    {
        $game->trace("Executing PlayerTurn state - checking player progress");

        $currentRound = $game->getGameStateValue('round');
        $expectedCardCount = $currentRound + 1; // +1 for the initial card
        $game->debug("Current round: $currentRound, expected card count: $expectedCardCount");

        $deckCardPicked = $game->getUniqueValueFromDB("SELECT marketCardPicked FROM playerData WHERE marketCardPicked IS NOT NULL");

        if ($deckCardPicked != null) {
            $game->trace("Deck card picked still on Game State Zombie Detected, shuffling deck");
            $game->DbQuery("UPDATE playerData SET marketCardPicked = NULL");
            Market::shuffleDeck($game);
        }

        // Get the count of cards placed by each player, ordered by leader_id
        $game->debug("Retrieving card counts for all players");
        $cardCounts = $game->getCollectionFromDB(
            "SELECT p.player_id, COUNT(bm.movement_id) as card_count
             FROM player p
             JOIN playerData pd ON p.player_id = pd.player_id
             LEFT JOIN boards_moves bm ON pd.leader_id = bm.board_id
             WHERE p.player_eliminated = 0 AND p.player_zombie = 0
             GROUP BY p.player_id
             ORDER BY pd.leader_id ASC"
        );

        // Check if all players have the expected number of cards
        $allPlayersReachedTarget = true;

        foreach ($cardCounts as $playerId => $data) {
            $count = (int) $data['card_count'];
            $game->debug("Player ID: $playerId has $count cards");

            if ($count < $expectedCardCount) {
                $game->debug("Player ID: $playerId has not reached target card count");
                $allPlayersReachedTarget = false;
                break;
            }
        }

        $game->debug("Refreshing market cards");

        $marketCards = Market::getAllMarketCards($game);
        $game->debug("Retrieved " . count($marketCards) . " market cards");

        $game->trace("Notifying players about market update");
        $game->notifyAllPlayers("marketUpdate", "", [
            "cards" => $marketCards,
            "cardsInDeck" => Market::getCardsInDeck($game)
        ]);

        // If all players have reached the expected card count, transition to attack phase
        // Otherwise, go to next player
        if ($allPlayersReachedTarget) {
            $game->trace("All players have reached target card count, moving to attack phase");
            Players::activateNextPlayer($game);
            $game->gamestate->nextState('startAtkPhase');
        } else {
            $game->trace("Not all players have reached target card count, moving to next player");
            Players::activateNextPlayer($game);
            $game->gamestate->nextState('nextPlayer');
        }
    }
}
